const sw = (S, k, x, y, w, h, bg, st, o = {}) => { S.el(k, { x, y, w, h, html: ex(o.html || ''), cls: o.cls || '', css: `border-radius:${o.r ?? .2}em;${/--line\)/.test(bg) && !o.css ? 'border:.06em solid var(--line);' : ''}${o.css || ''}`, s: Object.assign(st ? hid() : {}, { background: bg }) }); vis(S, k, st, o.off); };
const cl = (S, k, x, y, w, t, c, st, o = {}) => T(S, k, x, y, t, 'cz-tc clx-xs ' + clsOf(c), st, Object.assign({ w }, o));
const nd = (S, k, x, y, w, label, color, st, o = {}) => chip(S, k, x, y, w, label, color || 'line', st, Object.assign({ pct: 14 }, o));
const ed = (S, k, a, b, st, o = {}) => seg(S, k, a, b, st, o.color || 'ink-3', o.h || .08, { off: o.off });
const tbox = (S, k, x, y, w, h, title, color, st, o = {}) => { frame(S, k, x, y, w, h, color, st, { w: .1, off: o.off, dash: o.dash, r: .4 }); lbl(S, k + 't', x + .3, y + .15, title, 'm ' + (o.tc || ''), st, { off: o.off }); };
/* a three-column provider table: rows of [label, aws, azure, gcp] */
const ptable = (S, k, X, y, rows, st, o = {}) => { [['AWS', 'warn'], ['Azure', 'accent'], ['GCP', 'ok']].forEach(([t, c], j) => lbl(S, k + 'h' + j, X + 2.8 + j * 3.3, y, t, 'm ' + (c === 'warn' ? 'w' : c === 'accent' ? 'a' : 'g'), st, { off: o.off })); rows.forEach((r, i) => { lbl(S, k + 'r' + i, X, y + .8 + i * .75, r[0], 'm', st, { off: o.off }); r.slice(1).forEach((t, j) => lbl(S, k + 'c' + i + j, X + 2.8 + j * 3.3, y + .8 + i * .75, t, 'm', st, { off: o.off })); }); };

function sRegions() {
  return CW('cl-regions-az', {
    code: [['# 리전: 지리적으로 떨어진 데이터센터 묶음', '# region: a geographic group of data centers'], ['ap-northeast-2   # AWS 서울', 'ap-northeast-2   # AWS Seoul'], 'koreacentral     # Azure', ['asia-northeast3  # GCP 서울', 'asia-northeast3  # GCP Seoul'], ['# 가용 영역(AZ): 리전 안의 독립된 구역', '# availability zone: isolated area in a region'], 'ap-northeast-2a / 2b / 2c / 2d'],
    hl: [[0, 4], [4, 2, 'ok'], [5, 1, 'warn'], [1, 1]],
    lh: 1.3,
    draw: (S) => {
      const X = 19.4;
      tbox(S, 'rg', X, .6, 12.0, 5.2, ['리전 (서울)', 'region (Seoul)'], 'accent', 1, { tc: 'a' });
      lbl(S, 'n1', X, 6.6, ['사용자와 가까운 리전 · 법규(데이터 위치)도 고려', 'pick regions near users and within data laws'], 'a', 1, { off: 2, w: 12 });
      ['a', 'b', 'c'].forEach((t, i) => { frame(S, 'az' + i, X + .4 + i * 3.9, 1.5, 3.5, 3.8, 'ok', 2, { w: .1, dash: 1 }); lbl(S, 'azl' + i, X + .6 + i * 3.9, 1.6, 'AZ ' + t, 'm g', 2); });
      lbl(S, 'n2', X, 6.6, ['AZ마다 전원·냉각·네트워크가 따로 · 빠른 전용망으로 연결', 'each AZ has separate power and network, linked by fast fiber'], 'g', 2, { off: 3, w: 12 });
      [0, 1, 2].forEach(i => nd(S, 'app' + i, X + .8 + i * 3.9, 2.6, 2.7, 'app', 'warn', 3, { h: .9 })); [0, 1].forEach(i => nd(S, 'db' + i, X + .8 + i * 3.9, 3.9, 2.7, i ? 'DB ↻' : 'DB', 'line', 3, { h: .9 }));
      lbl(S, 'n3', X, 6.6, ['여러 AZ에 나눠 두면 한 곳이 멈춰도 계속 서비스', 'spreading across AZs survives one AZ failing'], 'w', 3, { off: 4, w: 12 });
      sw(S, 'x', X + .4, 1.5, 3.5, 3.8, 'rgba(220,40,40,.18)', 4, { css: 'z-index:4' }); lbl(S, 'n4', X, 6.6, ['AZ a 장애 → b, c가 트래픽을 넘겨받아요', 'AZ a fails → b and c take the traffic'], 'r', 4, { w: 12 });
    },
    notes: [['리전은 서울, 도쿄처럼 지리적으로 떨어진 데이터센터 묶음이에요 · 사용자와 가까울수록 지연이 줄고, 데이터가 어느 나라에 있어야 하는지 같은 법규도 따져요', 'a region is a geographically separate group of data centers such as Seoul or Tokyo; nearness to users cuts latency, and data residency laws matter too'], ['가용 영역(AZ)은 한 리전 안에서 전원, 냉각, 네트워크가 독립된 구역이에요 · AZ끼리는 지연이 아주 짧은 전용망으로 연결돼요', 'availability zones are areas within a region with independent power, cooling and networking, linked by very low-latency private fiber'], ['앱 서버와 DB 복제본을 여러 AZ에 나눠 두면 한 AZ에 문제가 생겨도 서비스가 계속돼요', 'spreading app servers and database replicas across AZs keeps the service running when one AZ has trouble'], ['AZ 하나가 멈추면 로드밸런서가 나머지 AZ로 트래픽을 보내고, 대기 DB가 승격돼요 · 리전 전체 장애에는 다중 리전이 필요해요', 'when one AZ stops, the load balancer shifts traffic and a standby database is promoted, while whole-region outages need multiple regions']],
    fin: [['리전과 가용 영역: 클라우드 인프라의 지리적 단위 · 고가용성은 “여러 AZ에 나눠 두기”에서 시작해요', 'regions and AZs are the cloud’s geographic units, and high availability starts with spreading across AZs', 'clx-xs clx-a'], ['AZ 사이 데이터 전송에도 요금이 붙어요', 'data transfer between AZs is billed too'], ['서비스마다 지원 리전이 달라서 먼저 확인해요', 'service availability varies by region, so check first']],
    caps: [['리전', 'Regions'], ['가용 영역', 'Availability zones'], ['여러 AZ에 배치', 'Spreading across AZs'], ['AZ 장애', 'Surviving an AZ failure'], ['리전과 가용 영역', 'Regions and availability zones']]
  });
}

function sShared() {
  return CW('cl-shared-responsibility', {
    code: [['# 클라우드 “의” 보안: 제공자 책임', '# security OF the cloud: provider'], ['#   데이터센터 · 하드웨어 · 가상화 계층', '#   data centers, hardware, virtualization'], ['# 클라우드 “안”의 보안: 고객 책임', '# security IN the cloud: customer'], ['#   데이터 · IAM · 설정 · OS 패치 · 앱', '#   data, IAM, config, OS patches, apps'], ['# 관리형일수록 고객 몫이 줄어요', '# more managed, less for the customer']],
    hl: [[0, 2, 'ok'], [2, 2, 'warn'], [4, 1], [3, 1, 'danger']],
    lh: 1.3,
    draw: (S) => {
      const X = 19.4, L = [['data · IAM', 1, 1, 1], ['app', 1, 1, 0], ['OS', 1, 0, 0], ['runtime/VM', 0, 0, 0], ['hardware', 0, 0, 0]];
      [['IaaS', 0], ['PaaS', 1], ['SaaS', 2]].forEach(([t, j]) => lbl(S, 'h' + j, X + 3.6 + j * 2.9, .6, t, 'm a', 0));
      L.forEach(([t, a, b, c], i) => { lbl(S, 'l' + i, X, 1.4 + i * .9, t, 'm', 0); [a, b, c].forEach((v, j) => sw(S, 'c' + i + j, X + 3.4 + j * 2.9, 1.3 + i * .9, 2.7, .7, v ? tint('warn', 55) : tint('ok', 45), 1, { css: 'z-index:3' })); });
      lbl(S, 'lg1', X, 6.0, ['■ 고객', '■ customer'], 'm w', 1); lbl(S, 'lg2', X + 3.0, 6.0, ['■ 제공자', '■ provider'], 'm g', 1);
      lbl(S, 'n1', X, 7.0, ['어디까지가 내 몫인지가 서비스 모델마다 달라요', 'the customer’s share differs by service model'], 'a', 1, { off: 2, w: 12 });
      frame(S, 'f0', X + 3.3, 1.2, 2.9, 4.5, 'warn', 2, { off: 3, w: .12 }); lbl(S, 'n2', X, 7.0, ['IaaS: OS 패치·방화벽까지 고객이', 'IaaS: OS patches and firewalls are yours'], 'w', 2, { off: 3, w: 12 });
      frame(S, 'f1', X - .1, 1.2, 12.0, .9, 'danger', 3, { off: 4, w: .12 }); lbl(S, 'n3', X, 7.0, ['데이터와 권한 설정은 언제나 고객 책임', 'data and access settings are always yours'], 'r', 3, { off: 4, w: 12 });
      lbl(S, 'n4', X, 7.0, ['사고 대부분은 공개 버킷·과한 권한 같은 설정 실수', 'most incidents are misconfigs like public buckets'], 'a', 4, { w: 12 });
    },
    notes: [['클라우드 제공자는 데이터센터, 하드웨어, 가상화 계층처럼 “클라우드 자체”의 보안을 책임져요', 'the provider secures the cloud itself: data centers, hardware and the virtualization layer'], ['IaaS(가상 머신)를 쓰면 OS 패치, 방화벽 설정, 런타임까지 고객 몫이에요', 'with IaaS (virtual machines), OS patches, firewall settings and runtimes are the customer’s job'], ['서비스가 관리형(PaaS, SaaS)일수록 고객의 몫이 줄지만, 데이터와 접근 권한 설정은 어떤 모델이든 고객 책임이에요', 'more managed services (PaaS, SaaS) shrink the customer’s share, but data and access settings remain the customer’s in every model'], ['실제 사고 대부분은 공개된 스토리지 버킷, 너무 넓은 권한, 노출된 키 같은 고객 쪽 설정 실수에서 나와요', 'most real incidents come from customer-side misconfiguration such as public buckets, overly broad permissions and leaked keys']],
    fin: [['공동 책임 모델: 제공자는 클라우드“의” 보안, 고객은 클라우드 “안”의 보안 · 경계는 서비스 모델에 따라 이동해요', 'providers secure the cloud, customers secure what runs in it, and the line moves with the service model', 'clx-xs clx-a'], ['설정 점검 도구(AWS Config, Azure Policy 등)로 실수를 자동 감지해요', 'configuration checkers such as AWS Config or Azure Policy catch mistakes automatically'], ['규정 준수 인증은 제공자 몫만 보증해요', 'provider certifications only cover the provider’s share']],
    caps: [['제공자의 몫', 'The provider’s share'], ['IaaS의 고객 몫', 'The customer’s share in IaaS'], ['언제나 고객 몫', 'Always the customer’s'], ['설정 실수', 'Misconfigurations'], ['공동 책임 모델', 'The shared responsibility model']]
  });
}

function sServiceMap() {
  return CW('cl-service-map', {
    code: [['# 같은 개념, 다른 이름', '# same concepts, different names'], ['# 가상 머신 · 객체 스토리지 · 관리형 DB', '# VMs, object storage, managed DBs'], ['# 컨테이너 · 서버리스 · 메시징 · 권한', '# containers, serverless, messaging, IAM'], ['# 개념을 먼저 익히면 어디서든 통해요', '# learn the concept once, use it anywhere']],
    hl: [[1, 1], [2, 1, 'ok'], [3, 1, 'warn'], [0, 1]],
    lh: 1.4,
    draw: (S) => {
      const X = 19.4;
      ptable(S, 't1', X, .6, [['VM', 'EC2', 'VM', 'GCE'], ['object', 'S3', 'Blob', 'GCS'], ['SQL DB', 'RDS', 'Azure SQL', 'Cloud SQL']], 1, { off: 2 });
      lbl(S, 'n1', X, 6.6, ['기본 인프라는 세 곳 모두 비슷한 구성', 'core infrastructure looks alike across all three'], 'a', 1, { off: 2, w: 12 });
      ptable(S, 't2', X, .6, [['k8s', 'EKS', 'AKS', 'GKE'], ['CaaS', 'Fargate', 'Cont. Apps', 'Cloud Run'], ['function', 'Lambda', 'Functions', 'Run func.'], ['queue', 'SQS', 'Svc Bus', 'Pub/Sub']], 2, { off: 3 });
      lbl(S, 'n2', X, 6.6, ['컨테이너·서버리스·메시징도 대응 관계가 있어요', 'containers, serverless and messaging map too'], 'g', 2, { off: 3, w: 12 });
      ptable(S, 't3', X, .6, [['IAM', 'IAM', 'Entra ID', 'Cloud IAM'], ['secrets', 'SecretsMgr', 'Key Vault', 'Secret Mgr'], ['monitor', 'CloudWatch', 'Monitor', 'Monitoring'], ['NoSQL', 'DynamoDB', 'Cosmos DB', 'Firestore']], 3);
      lbl(S, 'n3', X, 6.6, ['세부 동작은 달라요 · 이름만 같다고 같진 않아요', 'details differ; a matching name is not identical behavior'], 'w', 3, { w: 12 });
    },
    notes: [['가상 머신(EC2, Azure VM, Compute Engine), 객체 스토리지(S3, Blob, GCS), 관리형 SQL(RDS, Azure SQL, Cloud SQL)처럼 기본 인프라는 세 클라우드 모두 비슷한 구성이에요', 'core infrastructure looks alike across the three: VMs (EC2, Azure VM, Compute Engine), object storage (S3, Blob, GCS) and managed SQL (RDS, Azure SQL, Cloud SQL)'], ['쿠버네티스(EKS, AKS, GKE), 서버리스 컨테이너, 함수, 메시지 큐도 서로 대응하는 서비스가 있어요', 'Kubernetes (EKS, AKS, GKE), serverless containers, functions and message queues have counterparts too'], ['권한, 비밀 관리, 모니터링, NoSQL도 대응되지만 세부 동작과 한계는 서비스마다 달라서 옮길 땐 문서로 확인해요', 'identity, secrets, monitoring and NoSQL map as well, but details and limits differ, so check docs when moving'], ['개념을 먼저 익히면 어떤 클라우드든 이름만 바꿔 같은 설계를 적용할 수 있어요', 'learning the concepts first lets you apply the same design on any cloud by swapping names']],
    fin: [['클라우드 서비스 대응: AWS·Azure·GCP는 이름은 달라도 비슷한 구성 요소를 제공해요 · 개념 중심으로 익혀요', 'AWS, Azure and GCP offer similar building blocks under different names, so learn the concepts first', 'clx-xs clx-a'], ['GCP의 VPC는 전역, AWS·Azure는 리전 단위처럼 구조 차이도 있어요', 'structures differ too: GCP VPCs are global while AWS and Azure networks are regional'], ['멀티 클라우드는 복잡도가 커서 이유가 분명할 때만', 'multicloud adds complexity, so do it only for clear reasons']],
    caps: [['기본 인프라', 'Core infrastructure'], ['컨테이너와 서버리스', 'Containers and serverless'], ['보안과 운영', 'Security and operations'], ['개념 중심', 'Concepts first'], ['서비스 대응표', 'Service mapping']]
  });
}

function sPricing() {
  return CW('cl-pricing', {
    code: [['# 온디맨드: 쓴 만큼, 약정 없음', '# on-demand: pay as you go'], ['# 약정 할인: 1·3년 약속하고 크게 할인', '# commitments: 1–3 years for big discounts'], ['#   Savings Plans · Reservations · CUD', '#   Savings Plans, Reservations, CUDs'], ['# 스팟: 남는 용량을 싸게 · 회수될 수 있음', '# spot: spare capacity, cheap, reclaimable'], ['# 숨은 비용: 데이터 전송(egress) · 유휴 자원', '# hidden: egress and idle resources']],
    hl: [[0, 1], [1, 2, 'ok'], [3, 1, 'warn'], [4, 1, 'danger']],
    lh: 1.3,
    draw: (S) => {
      const X = 19.4, bar = (k, y, w, c, t, st, o) => { sw(S, k, X + 3.4, y, w, .7, c, st, Object.assign({ css: 'z-index:3' }, o || {})); lbl(S, k + 'l', X, y + .05, t, 'm', st, o); };
      bar('od', .8, 8.0, 'var(--danger)', ['온디맨드', 'on-demand'], 1); lbl(S, 'odp', X + 11.5, .85, '100', 'm', 1);
      lbl(S, 'n1', X, 6.6, ['유연하지만 가장 비싸요 · 실험·예측 불가 부하에', 'flexible but priciest: for experiments and spiky load'], 'a', 1, { off: 2, w: 12 });
      bar('cm', 1.8, 4.8, 'var(--ok)', ['약정', 'committed'], 2); lbl(S, 'cmp', X + 8.4, 1.85, '~40–70', 'm g', 2);
      lbl(S, 'n2', X, 6.6, ['항상 켜 두는 기본 부하는 약정으로', 'commit for the always-on baseline'], 'g', 2, { off: 3, w: 12 });
      bar('sp', 2.8, 2.0, 'var(--warn)', ['스팟', 'spot'], 3); lbl(S, 'spp', X + 5.6, 2.85, ['~90% 할인 · 회수 가능', '≤90% off, reclaimable'], 'm w', 3);
      lbl(S, 'n3', X, 6.6, ['배치·CI처럼 중단돼도 되는 일에', 'for interruptible work such as batch and CI'], 'w', 3, { off: 4, w: 12 });
      nd(S, 'eg', X, 4.0, 5.8, ['나가는 데이터 전송', 'egress data'], 'danger', 4, { h: 1.0 }); nd(S, 'id', X + 6.2, 4.0, 5.8, ['꺼 두지 않은 자원', 'idle resources'], 'danger', 4, { h: 1.0 });
      lbl(S, 'n4', X, 6.6, ['들어오는 건 무료, 나가는 데이터는 유료', 'ingress is free; egress is billed'], 'r', 4, { w: 12 });
    },
    notes: [['온디맨드는 약정 없이 쓴 시간만큼 내는 방식이라 가장 유연하지만 가장 비싸요 · 실험이나 예측하기 어려운 부하에 맞아요', 'on-demand bills only for time used with no commitment, the most flexible and most expensive, suited to experiments and unpredictable load'], ['1년이나 3년 사용을 약속하면(AWS Savings Plans·Reserved Instances, Azure Reservations, GCP 약정 사용 할인) 크게 할인돼요 · 늘 켜 두는 기본 부하에 써요', 'commitments for one or three years (Savings Plans, Reservations, CUDs) give large discounts for always-on baseline load'], ['스팟(선점형)은 남는 용량을 아주 싸게 쓰지만 짧은 알림 뒤 회수될 수 있어요 · 배치, CI, 상태 없는 작업에 맞아요', 'spot (preemptible) capacity is very cheap but can be reclaimed after a short notice, fitting batch, CI and stateless work'], ['인터넷으로 나가는 데이터 전송(egress)과 꺼 두지 않은 자원이 예상 밖 비용의 큰 원인이에요', 'data transfer out to the internet (egress) and forgotten resources are major sources of surprise bills']],
    fin: [['클라우드 요금 모델: 온디맨드(유연) · 약정(기본 부하) · 스팟(중단 가능 작업)을 섞어 비용을 맞춰요', 'cloud pricing mixes on-demand for flexibility, commitments for the baseline and spot for interruptible work', 'clx-xs clx-a'], ['요금 계산기로 미리 추정해요', 'estimate ahead with pricing calculators'], ['예산 알림을 꼭 설정해요', 'always set budget alerts']],
    caps: [['온디맨드', 'On-demand'], ['약정 할인', 'Commitment discounts'], ['스팟', 'Spot'], ['숨은 비용', 'Hidden costs'], ['클라우드 요금 모델', 'Cloud pricing models']]
  });
}

