      lbl(S, 'cl', X, 4.4, ['조건', 'When'], 'm g', 2); nd(S, 'c', X + 2.6, 4.3, 9.4, ['사내망 IP에서만', 'only from office IPs'], 'ok', 2, { h: .9 }); lbl(S, 'n2', X, 6.6, ['조건으로 IP·시간·MFA·태그까지 좁혀요', 'conditions narrow by IP, time, MFA or tags'], 'g', 2, { off: 3, w: 12 });
