      nd(S, 'app', X, .8, 3.6, 'app', 'line', 2, { h: 1.0 }); arw(S, 'a0', [X + 3.65, 1.3], [X + 4.65, 1.3], 2); nd(S, 'sts', X + 4.7, .8, 3.0, 'STS', 'accent', 2, { h: 1.0 }); arw(S, 'a1', [X + 7.75, 1.3], [X + 8.65, 1.3], 2); nd(S, 'tok', X + 8.7, .8, 3.3, ['1시간 토큰', '1h token'], 'ok', 2, { h: 1.0 });
      lbl(S, 'n2', X, 6.6, ['역할을 맡으면 몇 시간짜리 임시 자격 증명', 'assuming a role yields credentials lasting hours'], 'g', 2, { off: 3, w: 12 });
      [['EC2/Lambda', 'role'], ['Azure VM/App', 'managed identity'], ['GCE/Cloud Run', 'service account']].forEach(([a, b], i) => { lbl(S, 'ra' + i, X, 2.6 + i * .8, a, 'm', 3); lbl(S, 'rb' + i, X + 5.0, 2.6 + i * .8, b, 'm a', 3); });
      lbl(S, 'n3', X, 6.6, ['클라우드 안의 코드는 플랫폼이 자격 증명을 넣어줘요', 'inside the cloud, the platform injects credentials'], 'a', 3, { off: 4, w: 12 });
      nd(S, 'gh', X, 5.0, 3.6, 'GitHub', 'line', 4, { h: .9 }); arw(S, 'g1', [X + 3.65, 5.45], [X + 4.65, 5.45], 4); chip(S, 'oidc', X + 4.7, 5.0, 3.0, 'OIDC', 'warn', 4, { h: .9 }); arw(S, 'g2', [X + 7.75, 5.45], [X + 8.65, 5.45], 4); nd(S, 'gr', X + 8.7, 5.0, 3.3, 'role', 'ok', 4, { h: .9 });
      lbl(S, 'n4', X, 6.6, ['CI도 저장된 키 없이 신원 연동으로 역할을 받아요', 'CI gets roles through federation, with no stored keys'], 'w', 4, { w: 12 });
