      lbl(S, 'n3', X, 6.6, ['DB 비밀번호를 자동으로 바꾸고 버전을 관리', 'rotate DB passwords automatically with versions'], 'w', 3, { off: 4, w: 12 });
      nd(S, 'au', X, 3.8, 12.0, ['감사 로그: 누가 언제 무엇을 읽었나', 'audit log: who read what, when'], 'ok', 4, { h: 1.0 }); lbl(S, 'n4', X, 6.6, ['캐시해서 읽되 교체 후엔 새로 받아요', 'cache reads but refresh after rotation'], 'a', 4, { w: 12 });
