      lbl(S, 'n2', X, 6.6, ['워크로드 성격에 맞는 인스턴스 계열을 골라요', 'pick the instance family that fits the workload'], 'g', 2, { off: 3, w: 12 });
      lbl(S, 'ph', X, 3.6, ['온디맨드 대비 가격', 'price vs on-demand'], 'm', 3); [[['온디맨드', 'on-demand'], '100%', 'line'], [['약정', 'committed'], '~30–70%', 'ok'], [['스팟', 'spot'], '~10–40%', 'warn']].forEach(([t, p, c], i) => { nd(S, 'p' + i, X + i * 4.1, 4.3, 3.8, t, c, 3, { h: 1.0 }); lbl(S, 'pl' + i, X + i * 4.1, 5.4, p, 'm', 3); });
      lbl(S, 'n3', X, 6.6, ['꾸준한 부하는 약정, 중단돼도 되는 일은 스팟', 'commit for steady load; spot for interruptible jobs'], 'w', 3, { off: 4, w: 12 });
      chip(S, 'sp', X + 6.6, 2.5, 5.4, ['30초~2분 예고', 'notice 30s–2m'], 'danger', 4, { h: 1.0 });
      lbl(S, 'n4', X, 6.6, ['스팟은 AWS 2분·Azure·GCP 30초 전에 알려요', 'spot notice: 2 min on AWS, 30 s on Azure and GCP'], 'r', 4, { w: 12 });
